    func test_swapaxes_moveaxis() {
        for (name, x) in layoutVariants(A3){
            XCTAssertClose(Matft.swapaxes(x, axis1: 0, axis2: 2), MfArray([0.0, -12.0, 4.0, 16.0, 8.0, 20.0, 1.0, 13.0, 5.0, 17.0, -9.0, -21.0, 2.0, 14.0, -6.0, -18.0, 10.0, 22.0, -3.0, -15.0, 7.0, 19.0, 11.0, 23.0] as [Double], mftype: .Double, shape: [4, 3, 2]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.swapaxes(x, axis1: 0, axis2: 2) \(name)")
