    func test_roll() {
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.roll(x, shift: 1), MfArray([8.0, 3.0, -1.0, 4.0, 1.0, 5.0, 9.0, -2.0, 6.0, 5.0, 3.0, 5.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.roll(x, shift: 1) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.roll(x, shift: 1, axis: 0), MfArray([5.0, 3.0, 5.0, 8.0, 3.0, -1.0, 4.0, 1.0, 5.0, 9.0, -2.0, 6.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.roll(x, shift: 1, axis: 0) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.roll(x, shift: 1, axis: 1), MfArray([1.0, 3.0, -1.0, 4.0, 6.0, 5.0, 9.0, -2.0, 8.0, 5.0, 3.0, 5.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.roll(x, shift: 1, axis: 1) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.roll(x, shift: 1, axis: -1), MfArray([1.0, 3.0, -1.0, 4.0, 6.0, 5.0, 9.0, -2.0, 8.0, 5.0, 3.0, 5.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.roll(x, shift: 1, axis: -1) \(name)")
        }
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.roll(x, shift: -1), MfArray([-1.0, 4.0, 1.0, 5.0, 9.0, -2.0, 6.0, 5.0, 3.0, 5.0, 8.0, 3.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.roll(x, shift: -1) \(name)")
