    func test_concatenate_dtypes() {
        XCTAssertClose(Matft.concatenate([U8, MfArray([-1, -128, 127] as [Int], mftype: .Int8, shape: [1, 3])], axis: 0), MfArray([0, 1, 127, 128, 254, 255, -1, -128, 127] as [Int], mftype: .Int16, shape: [3, 3]), rtol: 0, atol: 0, checkType: true, "Matft.concatenate([U8, MfArray([-1, -128, 127] as [Int], mftype: .Int8, shape: [1, 3])], axis: 0)")
        XCTAssertClose(Matft.concatenate([MfArray([-1, 2, 3] as [Int], mftype: .Int8, shape: [1, 3]), MfArray([200, 255, 0] as [Int], mftype: .UInt8, shape: [1, 3])], axis: 1), MfArray([-1, 2, 3, 200, 255, 0] as [Int], mftype: .Int16, shape: [1, 6]), rtol: 0, atol: 0, checkType: true, "Matft.concatenate([MfArray([-1, 2, 3] as [Int], mftype: .Int8, shape: [1, 3]), MfArray([200, 255, 0] as [Int], mftype: .UInt8, shape: [1, 3])], axis: 1)")
        XCTAssertClose(Matft.concatenate([AI, BL.astype(.Bool).reshape([3, 2])], axis: 1), MfArray([3, -1, 4, 1, 1, 0, 5, 9, -2, 6, 1, 0, 5, 3, 5, 8, 0, 1] as [Int], mftype: .Int, shape: [3, 6]), rtol: 0, atol: 0, checkType: true, "Matft.concatenate([AI, BL.astype(.Bool).reshape([3, 2])], axis: 1)")
        XCTAssertClose(Matft.concatenate([AI, A], axis: 0), MfArray([3.0, -1.0, 4.0, 1.0, 5.0, 9.0, -2.0, 6.0, 5.0, 3.0, 5.0, 8.0, 3.0, -1.0, 4.0, 1.0, 5.0, 9.0, -2.0, 6.0, 5.0, 3.0, 5.0, 8.0] as [Double], mftype: .Double, shape: [6, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.concatenate([AI, A], axis: 0)")
        XCTAssertClose(Matft.concatenate([AF, A], axis: 1), MfArray([3.0, -1.0, 4.0, 1.0, 3.0, -1.0, 4.0, 1.0, 5.0, 9.0, -2.0, 6.0, 5.0, 9.0, -2.0, 6.0, 5.0, 3.0, 5.0, 8.0, 5.0, 3.0, 5.0, 8.0] as [Double], mftype: .Double, shape: [3, 8]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.concatenate([AF, A], axis: 1)")
        XCTAssertClose(Matft.concatenate([AI, AF], axis: 0), MfArray([3.0, -1.0, 4.0, 1.0, 5.0, 9.0, -2.0, 6.0, 5.0, 3.0, 5.0, 8.0, 3.0, -1.0, 4.0, 1.0, 5.0, 9.0, -2.0, 6.0, 5.0, 3.0, 5.0, 8.0] as [Double], mftype: .Float, shape: [6, 4]), rtol: 1e-05, atol: 1e-05, checkType: true, "Matft.concatenate([AI, AF], axis: 0)")
        XCTAssertClose(Matft.vstack([U8, MfArray([-3, 4, 5] as [Int], mftype: .Int8, shape: [1, 3])]), MfArray([0, 1, 127, 128, 254, 255, -3, 4, 5] as [Int], mftype: .Int16, shape: [3, 3]), rtol: 0, atol: 0, checkType: true, "Matft.vstack([U8, MfArray([-3, 4, 5] as [Int], mftype: .Int8, shape: [1, 3])])")
        XCTAssertClose(Matft.hstack([MfArray([1, 2] as [Int], mftype: .UInt16), MfArray([-1] as [Int], mftype: .Int8)]), MfArray([1, 2, -1] as [Int], mftype: .Int32, shape: [3]), rtol: 0, atol: 0, checkType: true, "Matft.hstack([MfArray([1, 2] as [Int], mftype: .UInt16), MfArray([-1] as [Int], mftype: .Int8)])")
