            XCTAssertClose(Matft.hstack([x, C]), MfArray([3.0, -1.0, 4.0, 1.0, 1.0, 5.0, 9.0, -2.0, 6.0, -2.0, 5.0, 3.0, 5.0, 8.0, 3.0] as [Double], mftype: .Double, shape: [3, 5]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.hstack([x, C]) \(name)")
