    func test_append() {
        for (name, x) in layoutVariants(A){
            XCTAssertClose(Matft.append(x, values: B), MfArray([3.0, -1.0, 4.0, 1.0, 5.0, 9.0, -2.0, 6.0, 5.0, 3.0, 5.0, 8.0, 10.0, 11.0, 12.0, 13.0, 14.0, 15.0, 16.0, 17.0] as [Double], mftype: .Double, shape: [20]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.append(x, values: B) \(name)")
        }
        for (name, x) in layoutVariants(A){
