            XCTAssertClose(Matft.append(x, value: 7.5), MfArray([3.0, -1.0, 4.0, 1.0, 5.0, 9.0, -2.0, 6.0, 5.0, 3.0, 5.0, 8.0, 7.5] as [Double], mftype: .Double, shape: [13]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.append(x, value: 7.5) \(name)")
        }
        for (name, x) in layoutVariants(AI){
            XCTAssertClose(Matft.append(x, value: 7), MfArray([3, -1, 4, 1, 5, 9, -2, 6, 5, 3, 5, 8, 7] as [Int], mftype: .Int, shape: [13]), rtol: 0, atol: 0, checkType: true, "Matft.append(x, value: 7) \(name)")
        }
        for (name, x) in layoutVariants(V){
            XCTAssertClose(x.append(values: V), MfArray([7.0, -3.0, 0.0, 2.0, 7.0, -3.0, 0.0, 2.0] as [Double], mftype: .Double, shape: [8]), rtol: 1e-10, atol: 1e-10, checkType: true, "x.append(values: V) \(name)")
