    func test_nums() {
        XCTAssertClose(Matft.nums(7, shape: [2, 3]), MfArray([7, 7, 7, 7, 7, 7] as [Int], mftype: .Int, shape: [2, 3]), rtol: 0, atol: 0, checkType: true, "Matft.nums(7, shape: [2, 3])")
        XCTAssertClose(Matft.nums(2.5, shape: [2, 3], mftype: .Float), MfArray([2.5, 2.5, 2.5, 2.5, 2.5, 2.5] as [Double], mftype: .Float, shape: [2, 3]), rtol: 1e-05, atol: 1e-05, checkType: true, "Matft.nums(2.5, shape: [2, 3], mftype: .Float)")
        XCTAssertClose(Matft.nums(-1.25, shape: [3, 1, 2], mforder: .Column), MfArray([-1.25, -1.25, -1.25, -1.25, -1.25, -1.25] as [Double], mftype: .Double, shape: [3, 1, 2]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.nums(-1.25, shape: [3, 1, 2], mforder: .Column)")
        XCTAssertClose(Matft.nums(300, shape: [2], mftype: .UInt8), MfArray([44, 44] as [Int], mftype: .UInt8, shape: [2]), rtol: 0, atol: 0, checkType: true, "Matft.nums(300, shape: [2], mftype: .UInt8)")
        XCTAssertClose(Matft.nums(true, shape: [2, 2]), MfArray([true, true, true, true] as [Bool], shape: [2, 2]), rtol: 0, atol: 0, checkType: true, "Matft.nums(true, shape: [2, 2])")
        XCTAssertClose(Matft.nums_like(3, mfarray: A), MfArray([3.0, 3.0, 3.0, 3.0, 3.0, 3.0, 3.0, 3.0, 3.0, 3.0, 3.0, 3.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.nums_like(3, mfarray: A)")
        XCTAssertClose(Matft.nums_like(3.7, mfarray: AI), MfArray([3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3, 3] as [Int], mftype: .Int, shape: [3, 4]), rtol: 0, atol: 0, checkType: true, "Matft.nums_like(3.7, mfarray: AI)")
        XCTAssertClose(Matft.nums_like(-3.7, mfarray: AI), MfArray([-3, -3, -3, -3, -3, -3, -3, -3, -3, -3, -3, -3] as [Int], mftype: .Int, shape: [3, 4]), rtol: 0, atol: 0, checkType: true, "Matft.nums_like(-3.7, mfarray: AI)")
        XCTAssertClose(Matft.nums_like(-1, mfarray: U8), MfArray([255, 255, 255, 255, 255, 255] as [Int], mftype: .UInt8, shape: [2, 3]), rtol: 0, atol: 0, checkType: true, "Matft.nums_like(-1, mfarray: U8)")
        XCTAssertClose(Matft.nums_like(0.1, mfarray: AF), MfArray([0.10000000149011612, 0.10000000149011612, 0.10000000149011612, 0.10000000149011612, 0.10000000149011612, 0.10000000149011612, 0.10000000149011612, 0.10000000149011612, 0.10000000149011612, 0.10000000149011612, 0.10000000149011612, 0.10000000149011612] as [Double], mftype: .Float, shape: [3, 4]), rtol: 1e-05, atol: 1e-05, checkType: true, "Matft.nums_like(0.1, mfarray: AF)")
    }

    func test_empty_arrays() {
        XCTAssertClose(MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Row).reshape([0, 3]), MfArray([] as [Double], mftype: .Double, shape: [0, 3]), rtol: 1e-10, atol: 1e-10, checkType: true, "MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Row).reshape([0, 3])")
        XCTAssertClose(Matft.transpose(MfArray([] as [Double], mftype: .Double, shape: [2, 0, 3], mforder: .Row)), MfArray([] as [Double], mftype: .Double, shape: [3, 0, 2]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.transpose(MfArray([] as [Double], mftype: .Double, shape: [2, 0, 3], mforder: .Row))")
        XCTAssertClose(Matft.transpose(MfArray([] as [Double], mftype: .Double, shape: [2, 0, 3], mforder: .Row), axes: [1, 2, 0]), MfArray([] as [Double], mftype: .Double, shape: [0, 3, 2]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.transpose(MfArray([] as [Double], mftype: .Double, shape: [2, 0, 3], mforder: .Row), axes: [1, 2, 0])")
        XCTAssertClose(Matft.expand_dims(MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Row), axis: 1), MfArray([] as [Double], mftype: .Double, shape: [3, 1, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.expand_dims(MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Row), axis: 1)")
        XCTAssertClose(Matft.squeeze(Matft.expand_dims(MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Row), axis: 0)), MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.squeeze(Matft.expand_dims(MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Row), axis: 0))")
        XCTAssertClose(Matft.broadcast_to(MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Row), shape: [2, 3, 0]), MfArray([] as [Double], mftype: .Double, shape: [2, 3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.broadcast_to(MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Row), shape: [2, 3, 0])")
