        XCTAssertClose(Matft.flip(MfArray([] as [Double], mftype: .Double, shape: [2, 0, 3], mforder: .Row)), MfArray([] as [Double], mftype: .Double, shape: [2, 0, 3]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.flip(MfArray([] as [Double], mftype: .Double, shape: [2, 0, 3], mforder: .Row))")
        XCTAssertClose(Matft.swapaxes(MfArray([] as [Double], mftype: .Double, shape: [2, 0, 3], mforder: .Row), axis1: 0, axis2: 2), MfArray([] as [Double], mftype: .Double, shape: [3, 0, 2]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.swapaxes(MfArray([] as [Double], mftype: .Double, shape: [2, 0, 3], mforder: .Row), axis1: 0, axis2: 2)")
