        XCTAssertClose(MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Row).astype(.Float), MfArray([] as [Double], mftype: .Float, shape: [3, 0]), rtol: 1e-05, atol: 1e-05, checkType: true, "MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Row).astype(.Float)")
        XCTAssertClose(MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Row).astype(.Int), MfArray([] as [Int], mftype: .Int, shape: [3, 0]), rtol: 0, atol: 0, checkType: true, "MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Row).astype(.Int)")
        XCTAssertClose(Matft.sort(MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Row), axis: 0), MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.sort(MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Row), axis: 0)")
        XCTAssertClose(Matft.roll(MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Row), shift: 1), MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.roll(MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Row), shift: 1)")
