        XCTAssertClose(Matft.concatenate([MfArray([] as [Double], mftype: .Double, shape: [0, 4], mforder: .Row), A], axis: 0), MfArray([3.0, -1.0, 4.0, 1.0, 5.0, 9.0, -2.0, 6.0, 5.0, 3.0, 5.0, 8.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.concatenate([MfArray([] as [Double], mftype: .Double, shape: [0, 4], mforder: .Row), A], axis: 0)")
