        XCTAssertClose(MfArray([] as [Float], shape: [3, 0], mforder: .Row), MfArray([] as [Double], mftype: .Float, shape: [3, 0]), rtol: 1e-05, atol: 1e-05, checkType: true, "MfArray([] as [Float], shape: [3, 0], mforder: .Row)")
