        XCTAssertClose(MfArray([] as [Bool], shape: [3, 0], mforder: .Row), MfArray([] as [Bool], mftype: .Bool, shape: [3, 0]), rtol: 0, atol: 0, checkType: true, "MfArray([] as [Bool], shape: [3, 0], mforder: .Row)")
