        XCTAssertClose(MfArray([] as [Double], shape: [3, 0], mforder: .Column), MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "MfArray([] as [Double], shape: [3, 0], mforder: .Column)")
        XCTAssertClose(MfArray([] as [Float], shape: [3, 0], mforder: .Column), MfArray([] as [Double], mftype: .Float, shape: [3, 0]), rtol: 1e-05, atol: 1e-05, checkType: true, "MfArray([] as [Float], shape: [3, 0], mforder: .Column)")
        XCTAssertClose(MfArray([] as [Int], shape: [3, 0], mforder: .Column), MfArray([] as [Int], mftype: .Int, shape: [3, 0]), rtol: 0, atol: 0, checkType: true, "MfArray([] as [Int], shape: [3, 0], mforder: .Column)")
