        XCTAssertClose(MfArray([1, 255] as [UInt8]), MfArray([1, 255] as [Int], mftype: .UInt8, shape: [2]), rtol: 0, atol: 0, checkType: true, "MfArray([1, 255] as [UInt8])")
        XCTAssertClose(MfArray([-1, 2] as [Int8], shape: [2, 1]), MfArray([-1, 2] as [Int], mftype: .Int8, shape: [2, 1]), rtol: 0, atol: 0, checkType: true, "MfArray([-1, 2] as [Int8], shape: [2, 1])")
        XCTAssertClose(Matft.nums(1.0, shape: [0, 3]), MfArray([] as [Double], mftype: .Double, shape: [0, 3]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.nums(1.0, shape: [0, 3])")
