        XCTAssertClose(Matft.take(A, indices: MfArray([] as [Int], mftype: .Int, shape: [0]), axis: 1), MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.take(A, indices: MfArray([] as [Int], mftype: .Int, shape: [0]), axis: 1)")
