            if let im = z.imag { XCTAssertClose(im, MfArray([0.5, 7.0, -1.0, 2.0, -3.0, 9.0] as [Double], mftype: .Float, shape: [2, 3]), rtol: 1e-5, atol: 1e-5, checkType: true, "ZF.to_contiguous(mforder: .Column) imag") }
        }
        do {
